import os, re
from collections import defaultdict

def load_grids():
    d = os.environ.get('RLM_SESSION_DIR')
    t = open(d + '/../../sessions/' + os.path.basename(d) + '.jsonl').read().replace('\\n', '\n')
    G = {}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n', t):
        k, h, w = m[1], int(m[2]), int(m[3])
        content = t[m.end() : m.end() + h * w]
        rows = []
        pos = 0
        for _ in range(h):
            row_str = content[pos:pos+w].strip().split()
            rows.append([int(x) for x in row_str])
            pos += w
        if k not in G and all(len(r) == w for r in rows):
            G[k] = rows
    return G

G = load_grids()
print("Loaded grids:", sorted(G.keys()))

# Analyze demo 1
demo_input = G['Demo pair 1 (22x22)']
demo_output = G['Demo pair 1 output (22x22)']

