div_rows_demo = [3, 7, 11, 15, 19]
div_cols_demo = [3, 7, 11, 15, 19]

def parse_grid(grid, div_r, div_c):
    """Parse grid into cells"""
    num_cell_rows = len(div_r) - 1
    num_cell_cols = len(div_c) - 1

    cells = {}
    for i in range(num_cell_rows):
        for j in range(num_cell_cols):
            r_start, r_end = div_r[i], div_r[i+1]
            c_start, c_end = div_c[j], div_c[j+1]

            vals = []
            for r in range(r_start, r_end):
                for c in range(c_start, c_end):
                    vals.append(grid[r][c])

            # Get nonzero non-divider values
            nonzero_non8 = [v for v in vals if v != 0 and v != 8]

            cells[(i,j)] = {
                'positions': list(zip(range(r_start, r_end), range(c_start, c_end))),
                'all_vals': set(vals),
                'nonzero_non8': nonzero_non8,
                'dominant': None
            }

            if nonzero_non8:
                counts = Counter(nonzero_non8)
                cells[(i,j)]['dominant'] = counts.most_common(1)[0][0]

    return cells

