d = os.path.normpath(os.environ['RLM_SESSION_DIR'])
t = open(d + '/../../sessions/' + os.path.basename(d) + '.jsonl').read().replace('\\\\n', '\n')
G = {}

for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n', t):
    k, h, w = m[1], int(m[2]), int(m[3])
    rows = [r.split() for r in t[m.end():].split('\n')[:h]]
    if k not in G and all(len(r) == w and all(x.isdigit() for x in r) for r in rows):
        G[k] = [[int(x) for x in r] for r in rows]

test_in = G.get('Test input')

test_row_divs = [4, 8, 14, 18, 23]
test_col_divs = [4, 9, 14, 19, 24]

num_test_rows = len(test_row_divs) - 1
num_test_cols = len(test_col_divs) - 1

# Parse dots
test_dots = {}
for ci in range(num_test_rows):
    for cj in range(num_test_cols):
        r_start, r_end = test_row_divs[ci], test_row_divs[ci+1]
        c_start, c_end = test_col_divs[cj], test_col_divs[cj+1]

        flat_vals = [test_in[r][c] for r in range(r_start, r_end) for c in range(c_start, c_end) if test_in[r][c] != 8]
        nonzero = [(v, flat_vals.count(v)) for v in set(flat_vals) if v != 0 and v != 8]
        if nonzero:
            val = max(nonzero, key=lambda x: x[1])[0]
            test_dots[(ci,cj)] = val

print("Test dots:", test_dots)

cell_output = compute_expected_output(test_dots, num_test_rows, num_test_cols)

print("\nCell matrix:")
for ci in range(num_test_rows):
    print(' '.join(str(cell_output[(ci,cj)]) for cj in range(num_test_cols)))

# Build 28x28 with dividers
grid = []
for ri in range(28):
    # Get cell row index (-1 if in divider row area)
    cell_r_idx = sum(ri >= rd for rd in test_row_divs)

    row = []
    for ci in range(28):
        # Add column dividers (8s) at specific positions
        if ci in test_col_divs:
            row.append(8)
        # Add cell content
        elif cell_r_idx < num_test_rows:
            cell_c_idx = sum(ci >= cd for cd in test_col_divs)
            if cell_c_idx < num_test_cols:
                row.append(cell_output[(cell_r_idx, cell_c_idx)])
            else:
                row.append(0)
        else:
            row.append(0)

    # Ensure correct number of columns after inserting 8s
    while len(row) < 28:
        row.append(0)

    # Now insert 8s properly into each row
    new_row = [0] * 28
    pos = 0
    for i, val in enumerate(row):
        new_row[pos] = val
        pos += 1
        if i < 4 and i < 1:  # After first 5 columns (indices 0-4), pos would be 4+1=5
            pass
        if i == 4 or i == 9 or i == 14 or i == 19 or i == 24:
            pass  # Will handle below

    grid.append(new_row)

# Simpler approach
final_grid = [[0]*28 for _ in range(28)]

for ri in range(28):
    cr = sum(ri >= rd for rd in test_row_divs)
    for ci in range(28):
        cc = sum(ci >= cd for cd in test_col_divs)
        if ci in test_col_divs or ri in test_row_divs:
            final_grid[ri][ci] = 8
        elif cr < num_test_rows and cc < num_test_cols:
            final_grid[ri][ci] = cell_output[(cr, cc)]

with open('/tmp/test_output.json', 'w') as f:
    json.dump(final_grid, f)

print("\nPreview (first 15 rows):")
for i in range(15):
    print(' '.join(str(x) for x in final_grid[i][:20]))
